def strategy(my_history, opponent_history):
    round_no = len(my_history)

    if round_no == 0:
        return "cooperate"

    opp_betrays = opponent_history.count("betray")
    opp_coops = opponent_history.count("cooperate")

    # First 3 rounds: build trust
    if round_no < 3:
        return "cooperate"

    # If opponent never betrayed in first 5 rounds, exploit sometimes
    if round_no >= 5 and opp_betrays == 0:
        if round_no % 3 == 0:
            return "betray"
        return "cooperate"

    # If opponent betrayed last round, punish
    if opponent_history[-1] == "betray":
        return "betray"

    # If opponent betrays too much, always betray
    betray_rate = opp_betrays / len(opponent_history)
    if betray_rate > 0.45:
        return "betray"

    # Otherwise cooperate
    return "cooperate"

